import random


def gen():
    rng = random.Random(7)
    n, flights = 100, []
    for u in range(n):
        for v in rng.sample([x for x in range(n) if x != u], 10):
            flights.append([u, v, rng.randint(1, 1000)])
    return [n, flights, 0, n - 1, 6]

perf.naive:
def cheapest_fare(n: int, flights: list[list[int]], src: int, dst: int, k: int) -> int:
    adj = [[] for _ in range(n)]
    for u, v, price in flights:
        adj[u].append((v, price))
    best = float("inf")

    def go(city: int, spent: int, left: int) -> None:   # try every route of up to k + 1 flights
        nonlocal best
        if city == dst:
            best = min(best, spent)
            return
        if left == 0:
            return
        for nxt, price in adj[city]:
            go(nxt, spent + price, left - 1)

    go(src, 0, k + 1)
    return -1 if best == float("inf") else best
